3	/**
4	 * The three denominations an Account's balance may be held in.
5	 *
6	 * <p>Deliberately not {@link java.util.Currency}, which is open to every ISO 4217 code
7	 * there is. This context supports exactly three, so the type that names them should be
8	 * closed: a currency this service cannot price is then not a value anything can hold,
9	 * rather than a value some validator has to remember to reject.
10	 *
11	 * <p>Each constant carries the number of decimal places it is conventionally written
12	 * with, and {@link #decimalPlaces()} is the only place that fact lives. <b>It is read at
13	 * the edges and nowhere else</b> — the form that parses an operator's {@code "100.50"}
14	 * into Minor Units, the display that turns Minor Units back into it, and the
15	 * cross-currency conversion, which shifts by the difference between two scales. The core
16	 * counts Minor Units and never divides by a hundred.
17	 */
18	public enum Currency {
19	
20		EUR(2),
21		USD(2),
22	
23		/** The reason the scale shift in a conversion cannot be dropped: fillér are not counted in hundredths. */
24		HUF(0);
25	
26		private final int decimalPlaces;
27	
28		Currency(int decimalPlaces) {
29			this.decimalPlaces = decimalPlaces;
30		}
31	
32		/** How many decimal places an amount in this currency is written with: 2 for EUR and USD, 0 for HUF. */
33		public int decimalPlaces() {
34			return decimalPlaces;
35		}
36	}
