4	import org.junit.jupiter.api.DisplayName;
5	import org.junit.jupiter.api.Test;
6	import org.springframework.beans.factory.annotation.Autowired;
7	import org.springframework.boot.data.jpa.test.autoconfigure.DataJpaTest;
8	import org.springframework.boot.jpa.test.autoconfigure.TestEntityManager;
9	import org.springframework.boot.persistence.autoconfigure.EntityScan;
10	import org.springframework.test.context.TestPropertySource;
11	
12	import java.util.List;
13	
14	import static org.assertj.core.api.Assertions.assertThat;
15	
16	/**
17	 * One {@link Money} flattens to two columns, and the currency is a {@code varchar} holding
18	 * the currency's name.
19	 *
20	 * <p>Neither half is the default. Left unannotated, JPA stores an enum by its
21	 * <b>ordinal</b> — Hibernate 7 emits a {@code tinyint} — and reordering the constants
22	 * would then silently reinterpret every row already written. {@code @Enumerated(STRING)}
23	 * alone emits a <b>native H2 {@code enum}</b> column rather than a varchar, proved by
24	 * {@code RecordAsEmbeddableSpikeTest}, which is H2-specific in a schema the README's TODO
25	 * list says has to move to Postgres. Design decision 29 chose to pin {@code varchar}, and
26	 * that pin is one annotation whose loss nothing else would notice.
27	 *
28	 * <p>So this test is arranged the way the application really runs rather than the way a
29	 * JPA test usually is: the table comes from a migration and Hibernate is on
30	 * {@code validate}, exactly as ticket 08's accounts table will be. The mapping is checked
31	 * <em>against hand-written SQL</em> — remove the pin and the context fails to start
32	 * naming the column, which is the failure ticket 08 would otherwise meet while also
33	 * writing that SQL.
34	 *
35	 * <p>That arrangement is not only the more faithful one, it is the one that works.
36	 * {@code ddl-auto=create-drop} emits a check constraint for the enum —
37	 * {@code check (currency in ('EUR','USD','HUF'))} — which is unusable on the throwaway
38	 * database {@code @DataJpaTest} substitutes: every insert fails with H2's
39	 * {@code Check constraint invalid}, caused by {@code The database has been closed}. Since
40	 * Hibernate emits no DDL anywhere in this application, that is a dead end rather than a
41	 * problem worth solving.
42	 */
43	@DataJpaTest
44	@EntityScan(basePackageClasses = MoneyEmbeddingHost.class)
45	@TestPropertySource(properties = {
46			// The host entity is test-only, so its table ships beside this test rather than
47			// in db/migration, which Flyway owns for the schema the application runs on.
48			"spring.flyway.locations=classpath:db/testmigration/moneymapping",
49			// The application's own setting, restated because the claim below rests on it.
50			"spring.jpa.hibernate.ddl-auto=validate"
51	})
52	class MoneyMapsToTwoColumnsTest {
53	
54		@Autowired
55		private TestEntityManager entityManager;
56	
57		/**
58		 * Startup is half the assertion: {@code validate} has already compared the mapping
59		 * against the migration by the time this method runs. The body confirms the agreement
60		 * is a working one and not merely a nominal one.
61		 */
62		@Test
63		@DisplayName("the mapping agrees with a hand-written varchar column, and money round trips through it")
64		void roundTripsThroughAHandWrittenSchema() {
65			Money amount = new Money(123_45L, Currency.EUR);
66	
67			Long id = entityManager.persistAndGetId(new MoneyEmbeddingHost(amount), Long.class);
68			entityManager.flush();
69			entityManager.clear();
70	
71			assertThat(entityManager.find(MoneyEmbeddingHost.class, id).getAmount()).isEqualTo(amount);
72		}
73	
74		/**
75		 * Read in SQL rather than through Hibernate, so this asserts what is in the database
76		 * rather than what the mapping is willing to say about it. {@code 'HUF'} is the fact
77		 * that matters: stored by ordinal it would be a {@code 2}.
78		 *
79		 * <p>Note what the implicit naming strategy does <em>not</em> do — the host's field is
80		 * called {@code amount} and no column is named after it. An entity carrying two Money
81		 * figures therefore needs {@code @AttributeOverride} to keep them apart, which is
82		 * ticket 08's first job.
83		 */
84		@Test
85		@DisplayName("the count and the currency are stored as minor_units and a currency name")
86		void storesTheCountAndTheCurrencyName() {
87			entityManager.persistAndFlush(new MoneyEmbeddingHost(new Money(-150L, Currency.HUF)));
88			entityManager.clear();
89	
90			@SuppressWarnings("unchecked")
91			List<Object[]> rows = entityManager.getEntityManager()
92					.createNativeQuery("SELECT minor_units, currency FROM money_embedding_host")
93					.getResultList();
94	
95			assertThat(rows).hasSize(1);
96			assertThat(((Number) rows.getFirst()[0]).longValue()).isEqualTo(-150L);
97			assertThat(rows.getFirst()[1]).hasToString("HUF");
98		}
99	}
