1	package hu.bankmonitor.payments.common;
2	
3	import org.junit.jupiter.api.DisplayName;
4	import org.junit.jupiter.api.Nested;
5	import org.junit.jupiter.api.Test;
6	
7	import static org.assertj.core.api.Assertions.assertThat;
8	import static org.assertj.core.api.Assertions.assertThatThrownBy;
9	
10	class MoneyTest {
11	
12		@Nested
13		@DisplayName("equality")
14		class Equality {
15	
16			/**
17			 * The property design decision 16 chose {@code long} to get. {@code BigDecimal}
18			 * compares scale in {@code equals}, so the same amount written two ways compares
19			 * unequal; a count of Minor Units has no scale to disagree about.
20			 */
21			@Test
22			@DisplayName("two amounts of the same money are equal")
23			void comparesTheCountAndTheCurrency() {
24				assertThat(new Money(100_50L, Currency.EUR)).isEqualTo(new Money(100_50L, Currency.EUR));
25			}
26	
27			@Test
28			@DisplayName("the same count in a different currency is not the same money")
29			void separatesAmountsInDifferentCurrencies() {
30				assertThat(new Money(100L, Currency.EUR)).isNotEqualTo(new Money(100L, Currency.HUF));
31			}
32		}
33	
34		@Nested
35		@DisplayName("arithmetic")
36		class Arithmetic {
37	
38			@Test
39			@DisplayName("adding counts Minor Units, keeping the currency")
40			void adds() {
41				Money sum = new Money(100_50L, Currency.EUR).plus(new Money(24_99L, Currency.EUR));
42	
43				assertThat(sum).isEqualTo(new Money(125_49L, Currency.EUR));
44			}
45	
46			@Test
47			@DisplayName("subtracting counts Minor Units, keeping the currency")
48			void subtracts() {
49				Money difference = new Money(125_49L, Currency.EUR).minus(new Money(24_99L, Currency.EUR));
50	
51				assertThat(difference).isEqualTo(new Money(100_50L, Currency.EUR));
52			}
53	
54			/**
55			 * A balance may not go negative, but that is the Account's invariant and the
56			 * Account enforces it. A difference between two amounts is money too, and
57			 * refusing to represent it here would only push the subtraction out to bare
58			 * {@code long}s where nothing checks the currency.
59			 */
60			@Test
61			@DisplayName("a difference may be negative")
62			void subtractsPastZero() {
63				Money difference = new Money(100L, Currency.HUF).minus(new Money(250L, Currency.HUF));
64	
65				assertThat(difference).isEqualTo(new Money(-150L, Currency.HUF));
66			}
67	
68			@Test
69			@DisplayName("zero is an amount like any other, in a stated currency")
70			void hasAZeroPerCurrency() {
71				assertThat(Money.zero(Currency.USD)).isEqualTo(new Money(0L, Currency.USD));
72			}
73	
74			/**
75			 * Java's {@code +} wraps silently on overflow, which would turn the largest
76			 * possible balance into a negative one — the single way a count of Minor Units
77			 * can represent a quantity that is not the answer.
78			 */
79			@Test
80			@DisplayName("an addition that will not fit in a long is refused rather than wrapped")
81			void refusesToOverflow() {
82				Money theLargestAmountThereIs = new Money(Long.MAX_VALUE, Currency.HUF);
83	
84				assertThatThrownBy(() -> theLargestAmountThereIs.plus(new Money(1L, Currency.HUF)))
85						.isInstanceOf(ArithmeticException.class);
86			}
87	
88			@Test
89			@DisplayName("a subtraction that will not fit in a long is refused rather than wrapped")
90			void refusesToUnderflow() {
91				Money theSmallestAmountThereIs = new Money(Long.MIN_VALUE, Currency.HUF);
92	
93				assertThatThrownBy(() -> theSmallestAmountThereIs.minus(new Money(1L, Currency.HUF)))
94						.isInstanceOf(ArithmeticException.class);
95			}
96		}
97	
98		/**
99		 * Adding euros to forints is a bug in the caller, not a request a user made, so it is
100		 * an unchecked exception rather than a value some caller might forget to inspect.
101		 * Nothing catches it: cross-currency amounts meet only after a conversion (ticket 07)
102		 * has already made them one currency.
103		 */
104		@Nested
105		@DisplayName("operands in differing currencies")
106		class DifferingCurrencies {
107	
108			@Test
109			@DisplayName("adding across currencies is refused, naming both")
110			void refusesToAdd() {
111				Money euros = new Money(100_00L, Currency.EUR);
112				Money forints = new Money(100L, Currency.HUF);
113	
114				assertThatThrownBy(() -> euros.plus(forints))
115						.isInstanceOf(IllegalArgumentException.class)
116						.hasMessageContaining("EUR")
117						.hasMessageContaining("HUF");
118			}
119	
120			@Test
121			@DisplayName("subtracting across currencies is refused, naming both")
122			void refusesToSubtract() {
123				Money euros = new Money(100_00L, Currency.EUR);
124				Money dollars = new Money(100_00L, Currency.USD);
125	
126				assertThatThrownBy(() -> euros.minus(dollars))
127						.isInstanceOf(IllegalArgumentException.class)
128						.hasMessageContaining("EUR")
129						.hasMessageContaining("USD");
130			}
131	
132			@Test
133			@DisplayName("comparing across currencies is refused, naming both")
134			void refusesToCompare() {
135				Money forints = new Money(100L, Currency.HUF);
136				Money dollars = new Money(100L, Currency.USD);
137	
138				assertThatThrownBy(() -> forints.isLessThan(dollars))
139						.isInstanceOf(IllegalArgumentException.class)
140						.hasMessageContaining("HUF")
141						.hasMessageContaining("USD");
142			}
143	
144			/**
145			 * Without this, two amounts that have both lost their currency would combine
146			 * happily, because the guard above only compares them to each other.
147			 */
148			@Test
149			@DisplayName("a count with no currency is not money")
150			void refusesToExistWithoutACurrency() {
151				assertThatThrownBy(() -> new Money(100L, null)).isInstanceOf(NullPointerException.class);
152			}
153		}
154	
155		/**
156		 * The shape the overdraft check of ticket 13 is written in:
157		 * {@code availableBalance.isLessThan(amount)} refuses the transfer.
158		 */
159		@Nested
160		@DisplayName("comparison")
161		class Comparison {
162	
163			@Test
164			@DisplayName("a smaller count is less")
165			void ordersBySize() {
166				assertThat(new Money(99_99L, Currency.EUR).isLessThan(new Money(100_00L, Currency.EUR))).isTrue();
167				assertThat(new Money(100_01L, Currency.EUR).isLessThan(new Money(100_00L, Currency.EUR))).isFalse();
168			}
169	
170			/** The boundary the overdraft check turns on: spending an entire balance is allowed. */
171			@Test
172			@DisplayName("an equal amount is not less")
173			void treatsEqualAmountsAsNotLess() {
174				assertThat(new Money(100_00L, Currency.EUR).isLessThan(new Money(100_00L, Currency.EUR))).isFalse();
175			}
176	
177			@Test
178			@DisplayName("negative amounts order below zero")
179			void ordersNegativeAmounts() {
